export type ProcessResult =
    | { status: 'chargeable' }
    | { status: 'cancelled'; tryAgain?: boolean }
    | { status: 'failed'; error: Error };

/**
 * Initialize new tab and listen it
 */
export const process = (
    {
        Token,
        api,
        ApprovalURL,
        ReturnHost,
        signal,
    }: Pick<PaymentTokenResult, 'ApprovalURL' | 'ReturnHost' | 'Token'> & {
        api: Api;
        signal: AbortSignal;
    },
    delayListening = DELAY_LISTENING,
    delayPolling = DELAY_POLLING
): Promise<ProcessResult> => {
    const tab = window.open(ApprovalURL);

    return new Promise<ProcessResult>((resolve, reject) => {
        let settled = false;
        let polling = false;
        let tabClosed = false;
        let verificationStarted = false;
        let pollAttempts = 0;
        let listenTimer: number | undefined;
        let pollTimer: number | undefined;

        const cleanup = () => {
            window.clearTimeout(listenTimer);
            window.clearTimeout(pollTimer);
            tab?.close();
            // eslint-disable-next-line @typescript-eslint/no-use-before-define
            window.removeEventListener('message', onMessage, false);
            // eslint-disable-next-line @typescript-eslint/no-use-before-define
            signal.removeEventListener('abort', onAbort);
        };

        const finish = (result: ProcessResult) => {
            if (settled) {
                return;
            }
            settled = true;
            cleanup();
            resolve(result);
        };

        const fail = (error: unknown) => {
            if (settled) {
                return;
            }
            settled = true;
            cleanup();
            reject(error);
        };

        const checkStatus = async () => {
            if (settled || polling) {
                return;
            }

            polling = true;
            pollAttempts += 1;
            try {
                const { Status } = await api<{ Status: PAYMENT_TOKEN_STATUS }>({ ...getTokenStatus(Token), signal });
                if (settled) {
                    return;
                }
                if (Status === STATUS_CHARGEABLE) {
                    finish({ status: 'chargeable' });
                } else if (Status === STATUS_PENDING) {
                    if (tabClosed) {
                        finish({ status: 'cancelled', tryAgain: true });
                    } else if (pollAttempts >= MAX_POLL_ATTEMPTS) {
                        finish({ status: 'cancelled' });
                    } else {
                        pollTimer = window.setTimeout(() => void checkStatus(), delayPolling);
                    }
                } else {
                    finish({ status: 'failed', error: getStatusError(Status) });
                }
            } catch (error) {
                fail(error);
            } finally {
                polling = false;
            }
        };

        const listenTab = () => {
            if (settled || verificationStarted) {
                return;
            }
            if (tab?.closed) {
                tabClosed = true;
                window.clearTimeout(pollTimer);
                void checkStatus();
                return;
            }
            listenTimer = window.setTimeout(listenTab, delayListening);
        };

        const onMessage = (event: MessageEvent) => {
            if (settled || getHostname(event.origin) !== ReturnHost) {
                return;
            }

            verificationStarted = true;
            window.clearTimeout(listenTimer);
            tab?.close();

            if (event.data?.cancel === '1') {
                finish({ status: 'cancelled' });
                return;
            }

            window.clearTimeout(pollTimer);
            void checkStatus();
        };

        const onAbort = () => {
            tab?.close();
            finish({ status: 'cancelled' });
        };

        signal.addEventListener('abort', onAbort);
        window.addEventListener('message', onMessage, false);
        if (signal.aborted) {
            onAbort();
        } else {
            listenTab();
            void checkStatus();
        }
    });
};

