        jest.useFakeTimers();
        api = jest.fn();
        controller = new AbortController();
    });

    afterEach(() => {
        jest.useRealTimers();
    });

    const sendBankMessage = (data = {}) => {
        window.dispatchEvent(new MessageEvent('message', { origin: 'https://' + ReturnHost, data }));
    };

    it('opens the approval URL', async () => {
        const promise = process({ api, ApprovalURL, ReturnHost, signal: controller.signal, Token });

        expect(window.open).toHaveBeenCalledWith(ApprovalURL);

        controller.abort();
        await expect(promise).resolves.toEqual({ status: 'cancelled' });
    });

    it('resolves cancellation and removes listeners when the external signal aborts', async () => {
        const removeAbortListener = jest.spyOn(controller.signal, 'removeEventListener');
        const promise = process({ api, ApprovalURL, ReturnHost, signal: controller.signal, Token });

        expect(window.addEventListener).toHaveBeenCalledWith('message', expect.any(Function), false);
        const onMessage = (window.addEventListener as jest.Mock).mock.lastCall[1];

        controller.abort();

        await expect(promise).resolves.toEqual({ status: 'cancelled' });
        expect(window.removeEventListener).toHaveBeenCalledWith('message', onMessage, false);
        expect(removeAbortListener).toHaveBeenCalledWith('abort', expect.any(Function));
        expect(tab.close).toHaveBeenCalled();
        expect(jest.getTimerCount()).toBe(0);
    });

    it('resolves chargeable when the approval tab closes after verification', async () => {
        tab.closed = true;
        api.mockResolvedValue({ Status: PAYMENT_TOKEN_STATUS.STATUS_CHARGEABLE });

        const promise = process({ api, ApprovalURL, ReturnHost, signal: controller.signal, Token });

        await expect(promise).resolves.toEqual({ status: 'chargeable' });
        expect(api).toHaveBeenCalledTimes(1);
        expect(jest.getTimerCount()).toBe(0);
    });

    it('resolves cancellation when the approval tab closes while the token is pending', async () => {
        tab.closed = true;
        api.mockResolvedValue({ Status: PAYMENT_TOKEN_STATUS.STATUS_PENDING });

        const promise = process({ api, ApprovalURL, ReturnHost, signal: controller.signal, Token });

        await expect(promise).resolves.toEqual({ status: 'cancelled', tryAgain: true });
        expect(api).toHaveBeenCalledTimes(1);
        expect(jest.getTimerCount()).toBe(0);
    });

    it.each([
        PAYMENT_TOKEN_STATUS.STATUS_FAILED,
        PAYMENT_TOKEN_STATUS.STATUS_CONSUMED,
        PAYMENT_TOKEN_STATUS.STATUS_NOT_SUPPORTED,
    ])('resolves a failure when the approval tab closes with terminal status %s', async (Status) => {
        tab.closed = true;
        api.mockResolvedValue({ Status });

        const promise = process({ api, ApprovalURL, ReturnHost, signal: controller.signal, Token });

        await expect(promise).resolves.toEqual({ status: 'failed', error: expect.any(Error) });
        expect(jest.getTimerCount()).toBe(0);
    });

    it('polls pending status at the configured interval using simulated timers', async () => {
        api.mockResolvedValueOnce({ Status: PAYMENT_TOKEN_STATUS.STATUS_PENDING });
        api.mockResolvedValueOnce({ Status: PAYMENT_TOKEN_STATUS.STATUS_CHARGEABLE });

        const promise = process({ api, ApprovalURL, ReturnHost, signal: controller.signal, Token }, 10, 25);
        sendBankMessage();
        await Promise.resolve();

        expect(api).toHaveBeenCalledTimes(1);
        await jest.advanceTimersByTimeAsync(24);
        expect(api).toHaveBeenCalledTimes(1);
        await jest.advanceTimersByTimeAsync(1);

        await expect(promise).resolves.toEqual({ status: 'chargeable' });
        expect(api).toHaveBeenCalledTimes(2);
        expect(jest.getTimerCount()).toBe(0);
    });

    it.each([
        PAYMENT_TOKEN_STATUS.STATUS_FAILED,
        PAYMENT_TOKEN_STATUS.STATUS_CONSUMED,
        PAYMENT_TOKEN_STATUS.STATUS_NOT_SUPPORTED,
    ])('resolves terminal status %s while polling and stops further polling', async (Status) => {
        api.mockResolvedValueOnce({ Status: PAYMENT_TOKEN_STATUS.STATUS_PENDING });
        api.mockResolvedValueOnce({ Status });

        const promise = process({ api, ApprovalURL, ReturnHost, signal: controller.signal, Token }, 10, 25);
        sendBankMessage();
        await jest.advanceTimersByTimeAsync(25);

        await expect(promise).resolves.toEqual({ status: 'failed', error: expect.any(Error) });
        expect(api).toHaveBeenCalledTimes(2);
        expect(jest.getTimerCount()).toBe(0);
    });

    it('stops pending polling when the external signal aborts', async () => {
        api.mockResolvedValue({ Status: PAYMENT_TOKEN_STATUS.STATUS_PENDING });

        const promise = process({ api, ApprovalURL, ReturnHost, signal: controller.signal, Token }, 10, 25);
        sendBankMessage();
        await Promise.resolve();
        expect(api).toHaveBeenCalledTimes(1);

        controller.abort();

        await expect(promise).resolves.toEqual({ status: 'cancelled' });
        await jest.advanceTimersByTimeAsync(100);
        expect(api).toHaveBeenCalledTimes(1);
        expect(jest.getTimerCount()).toBe(0);
    });

    it('resolves cancellation when the bank approval message requests it', async () => {
        const promise = process({ api, ApprovalURL, ReturnHost, signal: controller.signal, Token });
        sendBankMessage({ cancel: '1' });

        await expect(promise).resolves.toEqual({ status: 'cancelled' });
        expect(api).not.toHaveBeenCalled();
        expect(jest.getTimerCount()).toBe(0);
    });
});

